-- 升級關卡用的固定資料（交接包 physical-v1.2 UPGRADE.md 的驗收案例）。
-- 在「上一版」的資料庫裡建好，升級後由 upgrade_verify 逐筆比對；必須相容上一版的 schema，
-- 所以只用既有欄位、每個沒有伺服器預設值的必填欄位都明寫。全是示範資料（RFC 5737 位址、假名稱）。
--   2 個配電盤、3 個迴路、9 個插座、8 條纜線；跨機房、雙電源、正背面同一 U、空線標、已除役的線、
--   未知瓦數（max_watts 空白）、面板正背面配對。
BEGIN;
-- 正背面同一 U：fx-srv-front 與 fx-srv-rear 都在 U10；fx-desk 未入櫃；fx-xroom 在另一個機房
UPDATE device_ports SET peer_port_id = '0f000000-0000-4000-8000-000000000036' WHERE id = '0f000000-0000-4000-8000-000000000035';
UPDATE device_ports SET peer_port_id = '0f000000-0000-4000-8000-000000000035' WHERE id = '0f000000-0000-4000-8000-000000000036';
-- 8 條纜線：一條空線標、一條已除役、一條跨機房
-- 電力：2 個配電盤、3 個迴路、9 個插座；雙電源接兩路、未知瓦數、跨機櫃
SELECT ('0f000000-0000-4000-8000-0000000008' || lpad(to_hex(n), 2, '0'))::uuid,
       CASE WHEN n <= 4 THEN '0f000000-0000-4000-8000-000000000071'::uuid
            WHEN n <= 8 THEN '0f000000-0000-4000-8000-000000000072'::uuid
            ELSE '0f000000-0000-4000-8000-000000000073'::uuid END,
       CASE WHEN n <= 8 THEN '0f000000-0000-4000-8000-000000000011'::uuid ELSE '0f000000-0000-4000-8000-000000000012'::uuid END,
       'FX-O' || n, now(), now()
FROM generate_series(1, 9) AS n;
COMMIT;
